from math import gcd

MOD = 10**9 + 7

def modular_inverse(x, mod):
    # Fermat's little theorem for modular inverse
    return pow(x, mod - 2, mod)

def expected_length(m):
    phi = list(range(m + 1))
    for i in range(2, m + 1):
        if phi[i] == i:  # i is a prime number
            for j in range(i, m + 1, i):
                phi[j] *= (i - 1)
                phi[j] //= i

    result = 0
    for i in range(1, m + 1):
        result += phi[i] * modular_inverse(i, MOD)
        result %= MOD

    return (result * modular_inverse(m, MOD)) % MOD

def main():
    input = sys.stdin.read
    m = int(input().strip())
    print(expected_length(m))

